INSERT INTO t_p96441965_look_app_redesign.articles
  (owner_user_id, title, cover_image, body, kind, steps, materials, duration, difficulty)
VALUES (
  'u_259dd4c92c95a437',
  'Расписной горшок для цветов своими руками',
  'https://cdn.poehali.dev/projects/82eb0b6d-91ae-4d3d-a0a1-a53fb8c6e823/files/ee68f07c-2498-4060-9243-805c09c494f7.jpg',
  'Обычный глиняный горшок за час превращается в красивый предмет интерьера. Подойдёт в подарок или для своего подоконника.',
  'tutorial',
  '[{"title":"Подготовьте горшок","text":"Протрите горшок влажной тряпкой и дайте ему полностью высохнуть. Если поверхность шершавая, пройдитесь мелкой наждачкой.","image":""},{"title":"Нанесите грунтовку","text":"Покройте горшок снаружи белой акриловой краской в один слой. Оставьте сохнуть 30 минут, затем нанесите второй слой, если первый просвечивает.","image":"https://cdn.poehali.dev/projects/82eb0b6d-91ae-4d3d-a0a1-a53fb8c6e823/files/d6f7c0bb-a5a0-4e5c-897c-9e529522a5be.jpg"},{"title":"Разметьте рисунок","text":"Простым карандашом слегка наметьте узор: полоски, треугольники или волну по краю. Лишнее потом закроет краска.","image":""},{"title":"Распишите узор","text":"Тонкой кистью нарисуйте узор зелёной и белой краской. Начинайте с крупных деталей, мелкие добавляйте в конце. Дайте краске высохнуть 1 час.","image":""},{"title":"Закрепите лаком","text":"Покройте горшок прозрачным акриловым лаком, чтобы краска не стиралась при поливе. Подождите сутки перед посадкой растения.","image":""},{"title":"Посадите растение","text":"Насыпьте на дно дренаж, добавьте землю и посадите суккулент или любимый цветок. Готово: поставьте горшок на подоконник.","image":"https://cdn.poehali.dev/projects/82eb0b6d-91ae-4d3d-a0a1-a53fb8c6e823/files/a2a2f0dd-5187-4066-b1d6-8d43b7a83f02.jpg"}]',
  E'Глиняный горшок\nБелая акриловая краска\nЗелёная акриловая краска\nТонкая и широкая кисти\nПростой карандаш\nПрозрачный акриловый лак\nМелкая наждачная бумага',
  '2 часа + сутки сушки',
  'easy'
);